/// <summary>
/// Persisted per-VAT-rate amounts of every reported payment, for netting partial payments: the
/// confirm-payment dialog pre-fills each rate with the invoice amount LESS what these lines
/// already reported at that rate. Re-reporting already-reported money is the mismatch Clear
/// rejects. Zero-amount entries are not persisted.
/// </summary>
public class CELTPaymentReportLine extends common
{
}

Method.Source:
/// <summary>
/// Sum already reported for one document at one VAT rate.
/// </summary>
/// <param name = "_documentId">business document number (the invoice number)</param>
/// <param name = "_rate">VAT rate</param>
/// <returns>amount collected (including VAT) reported so far</returns>
public static AmountCur collectedForRate(str _documentId, real _rate)
{
    CELTPaymentReportLine line;

    select sum(AmountCollected) from line
        where line.DocumentId == _documentId
           && line.Rate       == _rate;

    return line.AmountCollected;
}

/// <summary>
/// Total reported for one document across all rates and payments.
/// </summary>
/// <param name = "_documentId">business document number (the invoice number)</param>
/// <returns>total amount collected (including VAT) reported so far</returns>
public static AmountCur totalCollectedFor(str _documentId)
{
    CELTPaymentReportLine line;

    select sum(AmountCollected) from line
        where line.DocumentId == _documentId;

    return line.AmountCollected;
}
